import { Table, GuidColumn, ReferenceColumn, StringColumn, TranslatedFieldColumn } from '../../db'

/**
 * Business Calendar Entry Name - the reusable, translatable label a calendar entry
 * carries. Referenced from `business_calendar_span.span_name`.
 */
export const business_calendar_span_name = Table({
    display: 'label',
    extends: 'sys_metadata',
    label: 'Business Calendar Entry Name',
    name: 'business_calendar_span_name',
    schema: {
        calendar: ReferenceColumn({
            label: 'Calendar',
            mandatory: true,
            referenceTable: 'business_calendar',
        }),
        label: StringColumn({
            label: 'Label',
            maxLength: 80,
        }),
        long_name: TranslatedFieldColumn({
            label: 'Long name',
            mandatory: true,
            maxLength: 240,
        }),
        short_name: TranslatedFieldColumn({
            label: 'Short name',
            mandatory: true,
            maxLength: 80,
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
    },
})
